class Solution {
public:
    int scoreOfStudents(string s, vector<int>& answers) {
        vector<int> nums;
        vector<char> ops;
        for (size_t i = 0; i < s.size(); ++i) {
            if (i % 2 == 0) nums.push_back(s[i] - '0');
            else ops.push_back(s[i]);
        }
        vector<int> mulStack;
        mulStack.push_back(nums[0]);
        for (size_t i = 0; i < ops.size(); ++i) {
            if (ops[i] == '*') mulStack.back() *= nums[i + 1];
            else mulStack.push_back(nums[i + 1]);
        }
        int correct = 0;
        for (int x : mulStack) correct += x;

        int n = nums.size();
        vector<vector<unordered_set<int>>> dp(n, vector<unordered_set<int>>(n));
        for (int i = 0; i < n; ++i) dp[i][i].insert(nums[i]);

        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                for (int k = i; k < j; ++k) {
                    char op = ops[k];
                    for (int left : dp[i][k]) {
                        for (int right : dp[k + 1][j]) {
                            int val = (op == '*') ? (left * right) : (left + right);
                            if (val <= 1000) dp[i][j].insert(val);
                        }
                    }
                }
            }
        }
        int score = 0;
        const auto& possible = dp[0][n - 1];
        for (int ans : answers) {
            if (ans == correct) score += 5;
            else if (possible.count(ans)) score += 2;
        }
        return score;
    }
};

class Solution {
    public int scoreOfStudents(String s, int[] answers) {
        List<Integer> nums = new ArrayList<>();
        List<Character> ops = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            if (i % 2 == 0) nums.add(s.charAt(i) - '0');
            else ops.add(s.charAt(i));
        }
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(nums.get(0));
        for (int i = 0; i < ops.size(); i++) {
            if (ops.get(i) == '*') stack.push(stack.pop() * nums.get(i + 1));
            else stack.push(nums.get(i + 1));
        }
        int correct = 0;
        for (int x : stack) correct += x;

        int n = nums.size();
        Set<Integer>[][] dp = new HashSet[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) dp[i][j] = new HashSet<>();
            dp[i][i].add(nums.get(i));
        }
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                for (int k = i; k < j; k++) {
                    char op = ops.get(k);
                    for (int left : dp[i][k]) {
                        for (int right : dp[k + 1][j]) {
                            int val = (op == '*') ? (left * right) : (left + right);
                            if (val <= 1000) dp[i][j].add(val);
                        }
                    }
                }
            }
        }
        Set<Integer> possible = dp[0][n - 1];
        int score = 0;
        for (int ans : answers) {
            if (ans == correct) score += 5;
            else if (possible.contains(ans)) score += 2;
        }
        return score;
    }
}

var scoreOfStudents = function(s, answers) {
  const nums = [];
  const ops = [];
  for (let i = 0; i < s.length; i++) {
    if (i % 2 === 0) nums.push(Number(s[i]));
    else ops.push(s[i]);
  }
  const mulStack = [nums[0]];
  for (let i = 0; i < ops.length; i++) {
    if (ops[i] === '*') mulStack[mulStack.length - 1] *= nums[i + 1];
    else mulStack.push(nums[i + 1]);
  }
  const correct = mulStack.reduce((a, b) => a + b, 0);

  const n = nums.length;
  const dp = Array.from({ length: n }, () => Array.from({ length: n }, () => new Set()));
  for (let i = 0; i < n; i++) dp[i][i].add(nums[i]);

  for (let len = 2; len <= n; len++) {
    for (let i = 0; i <= n - len; i++) {
      const j = i + len - 1;
      for (let k = i; k < j; k++) {
        const op = ops[k];
        for (const left of dp[i][k]) {
          for (const right of dp[k + 1][j]) {
            const val = op === '*' ? left * right : left + right;
            if (val <= 1000) dp[i][j].add(val);
          }
        }
      }
    }
  }
  const possible = dp[0][n - 1];
  let score = 0;
  for (const ans of answers) {
    if (ans === correct) score += 5;
    else if (possible.has(ans)) score += 2;
  }
  return score;
};
